begin;
create table public.juniors_questions(id uuid primary key default gen_random_uuid(),slug text not null unique,subject text not null check(subject in('mathematics','physics','chemistry')),chapter_slug text not null,topic text not null,prompt text not null,options jsonb not null check(jsonb_typeof(options)='array'),correct_option smallint not null check(correct_option between 0 and 3),explanation text not null,difficulty text not null check(difficulty in('foundation','standard','advanced')),exam_tags text[] not null default '{}',status text not null default 'draft' check(status in('draft','review','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.juniors_practice_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,subject text check(subject in('mathematics','physics','chemistry')),exam_code text check(exam_code in('jee-main','tg-eapcet','ap-eapcet')),status text not null default 'active' check(status in('active','submitted','abandoned')),score smallint,total_questions smallint not null,started_at timestamptz not null default now(),submitted_at timestamptz);
create table public.juniors_practice_session_questions(session_id uuid not null references public.juniors_practice_sessions(id) on delete cascade,question_id uuid not null references public.juniors_questions(id) on delete restrict,display_order smallint not null,primary key(session_id,question_id),unique(session_id,display_order));
create table public.juniors_responses(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.juniors_practice_sessions(id) on delete cascade,question_id uuid not null references public.juniors_questions(id) on delete restrict,selected_option smallint not null check(selected_option between 0 and 3),is_correct boolean not null,answered_at timestamptz not null default now(),unique(session_id,question_id));
create index juniors_practice_user_started_idx on public.juniors_practice_sessions(user_id,started_at desc);create index juniors_session_questions_order_idx on public.juniors_practice_session_questions(session_id,display_order);create index juniors_responses_session_idx on public.juniors_responses(session_id);create index juniors_questions_browse_idx on public.juniors_questions(subject,chapter_slug,status);
alter table public.juniors_questions enable row level security;alter table public.juniors_practice_sessions enable row level security;alter table public.juniors_practice_session_questions enable row level security;alter table public.juniors_responses enable row level security;
create policy "published juniors questions readable" on public.juniors_questions for select to authenticated using(status='published');
create policy "practice sessions owner select" on public.juniors_practice_sessions for select to authenticated using((select auth.uid())=user_id);create policy "practice sessions owner insert" on public.juniors_practice_sessions for insert to authenticated with check((select auth.uid())=user_id);create policy "practice sessions owner update" on public.juniors_practice_sessions for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "session questions owner select" on public.juniors_practice_session_questions for select to authenticated using(exists(select 1 from public.juniors_practice_sessions s where s.id=session_id and s.user_id=(select auth.uid())));
create policy "responses owner select" on public.juniors_responses for select to authenticated using(exists(select 1 from public.juniors_practice_sessions s where s.id=session_id and s.user_id=(select auth.uid())));create policy "responses owner insert" on public.juniors_responses for insert to authenticated with check(exists(select 1 from public.juniors_practice_sessions s where s.id=session_id and s.user_id=(select auth.uid())));
revoke all on public.juniors_questions,public.juniors_practice_sessions,public.juniors_practice_session_questions,public.juniors_responses from anon;grant select on public.juniors_questions to authenticated;grant select,insert,update on public.juniors_practice_sessions to authenticated;grant select on public.juniors_practice_session_questions to authenticated;grant select,insert on public.juniors_responses to authenticated;
insert into public.juniors_questions(slug,subject,chapter_slug,topic,prompt,options,correct_option,explanation,difficulty,exam_tags,status) values
('math-quadratic-discriminant','mathematics','algebra','Quadratic equations','For x² − 6x + 9 = 0, what is the nature of the roots?','["Two distinct real roots","One repeated real root","Two non-real roots","No roots"]',1,'The discriminant is 36−36=0, so the equation has one repeated real root.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published'),
('math-derivative-power','mathematics','calculus','Differentiation','If f(x)=3x⁴, what is f′(2)?','["24","48","72","96"]',3,'f′(x)=12x³, and f′(2)=12×8=96.','standard',array['jee-main','tg-eapcet','ap-eapcet'],'published'),
('math-vector-magnitude','mathematics','vectors','Vector algebra','What is the magnitude of the vector 6i+8j?','["7","10","12","14"]',1,'Magnitude is √(6²+8²)=√100=10.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published'),
('physics-net-force','physics','mechanics','Laws of motion','A 4 kg body has a net force of 20 N. Its acceleration is:','["4 m/s²","5 m/s²","16 m/s²","80 m/s²"]',1,'Newton’s second law gives a=F/m=20/4=5 m/s².','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published'),
('physics-wave-length','physics','waves','Wave motion','A 200 Hz wave travels at 400 m/s. Find its wavelength.','["0.5 m","2 m","200 m","80000 m"]',1,'Using v=fλ, λ=400/200=2 m.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published'),
('physics-ohm-current','physics','electricity','Current electricity','A 12 V potential difference is applied to a 6 Ω resistor. The current is:','["0.5 A","2 A","6 A","72 A"]',1,'Ohm’s law gives I=V/R=12/6=2 A.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published'),
('chem-mole-particles','chemistry','physical-chemistry','Some basic concepts','How many molecules are present in 0.25 mol of a substance?','["1.5055×10²³","2.4088×10²⁴","6.022×10²³","0.25"]',0,'N=nNₐ=0.25×6.022×10²³=1.5055×10²³ molecules.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published'),
('chem-periodic-size','chemistry','inorganic-chemistry','Periodicity','Which atom is larger?','["Li","Na","They are equal","Cannot be predicted"]',1,'Atomic radius increases down group 1 because an additional electron shell is occupied.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published'),
('chem-functional-group','chemistry','organic-chemistry','Organic principles','Which functional group identifies a carboxylic acid?','["−OH","−CHO","−COOH","−NH₂"]',2,'Carboxylic acids contain the carboxyl group, −COOH.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published') on conflict(slug) do update set prompt=excluded.prompt,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,difficulty=excluded.difficulty,exam_tags=excluded.exam_tags,status='published',updated_at=now();
commit;
